// Enlace con pérdidas: 20 % de los pedidos y 20 % de las respuestas se pierden. Semilla fija.
function mulberry32(a) { return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

function simular(estrategia, semilla = 2026) {
  const azar = mulberry32(semilla);
  let stock = 1000;                         // el receptor descuenta 1 bulto por cada entrega que procesa
  const vistos = new Set();                 // ids ya procesados (solo si el receptor deduplica)
  let envios = 0, procesados = 0;
  const receptor = (id) => {                // devuelve true si la respuesta llega de vuelta
    if (azar() < 0.2) return false;         // se perdió el pedido: el receptor ni se entera
    if (estrategia === 'dedup' && vistos.has(id)) { /* ya estaba: no vuelve a descontar */ }
    else { stock--; procesados++; vistos.add(id); }
    return azar() >= 0.2;                   // la respuesta puede perderse
  };
  for (let id = 1; id <= 100; id++) {
    let ack = false, intentos = 0;
    do { intentos++; envios++; ack = receptor(id); }
    while (!ack && estrategia !== 'una-vez' && intentos < 10);
  }
  return { estrategia, entregas: 100, envios, descontados: 1000 - stock };
}
for (const e of ['una-vez', 'al-menos-una', 'dedup']) {
  const r = simular(e);
  console.log(r.estrategia.padEnd(13), 'envios=' + String(r.envios).padStart(3), ' bultos descontados=' + String(r.descontados).padStart(3), ' (correcto: 100)');
}

let stockA = 42, stockB = 42;
const restarUno = () => { stockA -= 1; };            // depende del estado anterior
const fijarEn = (n) => { stockB = n; };              // no depende de nada
for (let i = 0; i < 3; i++) { restarUno(); fijarEn(41); }
console.log('restar uno, aplicado 3 veces:', stockA, '| fijar en 41, aplicado 3 veces:', stockB);

// ¿Dónde anotar la clave de deduplicación? Tres órdenes, con una caída entre los dos pasos.
function correr(orden) {
  const db = { stock: 100, claves: new Set() };
  const mensaje = { id: 'entrega-5521' };
  const procesar = (caer) => {
    if (db.claves.has(mensaje.id)) return 'ya procesado, se ignora';
    if (orden === 'efecto-luego-clave') {
      db.stock--; if (caer) throw new Error('caída'); db.claves.add(mensaje.id);
    } else if (orden === 'clave-luego-efecto') {
      db.claves.add(mensaje.id); if (caer) throw new Error('caída'); db.stock--;
    } else {                                // una sola transacción: o los dos cambios o ninguno
      const copia = { stock: db.stock, claves: new Set(db.claves) };
      try { db.stock--; db.claves.add(mensaje.id); if (caer) throw new Error('caída'); }
      catch (e) { db.stock = copia.stock; db.claves = copia.claves; throw e; }
    }
    return 'procesado';
  };
  try { procesar(true); } catch (e) { /* el proceso cayó: el mensaje no se confirmó */ }
  console.log(orden.padEnd(20), '| tras la caída: stock=' + db.stock, 'clave=' + db.claves.has(mensaje.id));
  const r = procesar(false);              // el broker reentrega el mensaje
  console.log(' '.repeat(20), '| tras el reintento:', r, '-> stock=' + db.stock, '(correcto: 99)');
}
['efecto-luego-clave', 'clave-luego-efecto', 'misma-transaccion'].forEach(correr);
